node --version; echo "---"; cd /tmp
cat > pc.mjs <<'EOF'
import { readFileSync } from 'node:fs';
const raw = readFileSync('/proc/self/cmdline');
console.log('bytes:', [...raw].join(','));
console.log('argv:', JSON.stringify(process.argv));
console.log('parts:', JSON.stringify(raw.toString('latin1').split('\0')));
EOF
node pc.mjs --a "$(printf 'X\xffY')" --b b
echo "EXIT=$?"

cd /tmp
cat > u.mjs <<'EOF'
const NP = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
console.log('Cn ok:', NP.test('͸'));
console.log('Cs lone:', NP.test('\ud800'));
console.log('emoji:', NP.test('\u{1F600}'));
console.log('nbsp:', NP.test(' '));
console.log('zwsp:', NP.test('​'));
console.log('han:', NP.test('键'));
EOF
node u.mjs

