/**
 * UTF-8 codecs with Python's `surrogateescape` / `backslashreplace` error
 * handlers, needed to reproduce how CPython moves bytes between the OS and
 * `str` objects.
 */

import { hex, isSurrogate } from './unicode.mjs';

const CONT_MIN = 0x80;
const CONT_MAX = 0xbf;

function isCont(b) {
  return b >= CONT_MIN && b <= CONT_MAX;
}

/**
 * Decode bytes as UTF-8 using Python's `surrogateescape` error handler:
 * every byte that cannot take part in a well-formed UTF-8 sequence is mapped
 * to the lone surrogate U+DC00 + byte.
 *
 * The strict UTF-8 rules CPython enforces (and therefore we enforce) are:
 *   1 byte  : 00..7F
 *   2 bytes : C2..DF  80..BF                 (C0/C1 would be overlong)
 *   3 bytes : E0      A0..BF  80..BF         (no overlong)
 *             E1..EC  80..BF  80..BF
 *             ED      80..9F  80..BF         (no UTF-16 surrogates)
 *             EE..EF  80..BF  80..BF
 *   4 bytes : F0      90..BF  80..BF  80..BF (no overlong)
 *             F1..F3  80..BF  80..BF  80..BF
 *             F4      80..8F  80..BF  80..BF (max U+10FFFF)
 *
 * Escaping one byte at a time is equivalent to CPython's "maximal invalid
 * subsequence" reporting here, because every trailing byte of a rejected
 * sequence is a continuation byte, which is itself invalid as a leader.
 */
export function decodeUtf8SurrogateEscape(bytes) {
  let out = '';
  let i = 0;
  const n = bytes.length;
  while (i < n) {
    const b0 = bytes[i];
    if (b0 < 0x80) {
      out += String.fromCharCode(b0);
      i += 1;
      continue;
    }
    let size = 0;
    let cp = 0;
    if (b0 >= 0xc2 && b0 <= 0xdf) {
      if (i + 1 < n && isCont(bytes[i + 1])) {
        size = 2;
        cp = ((b0 & 0x1f) << 6) | (bytes[i + 1] & 0x3f);
      }
    } else if (b0 >= 0xe0 && b0 <= 0xef) {
      const lo = b0 === 0xe0 ? 0xa0 : 0x80;
      const hi = b0 === 0xed ? 0x9f : 0xbf;
      if (i + 2 < n && bytes[i + 1] >= lo && bytes[i + 1] <= hi && isCont(bytes[i + 2])) {
        size = 3;
        cp = ((b0 & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f);
      }
    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
      const lo = b0 === 0xf0 ? 0x90 : 0x80;
      const hi = b0 === 0xf4 ? 0x8f : 0xbf;
      if (
        i + 3 < n &&
        bytes[i + 1] >= lo &&
        bytes[i + 1] <= hi &&
        isCont(bytes[i + 2]) &&
        isCont(bytes[i + 3])
      ) {
        size = 4;
        cp =
          ((b0 & 0x07) << 18) |
          ((bytes[i + 1] & 0x3f) << 12) |
          ((bytes[i + 2] & 0x3f) << 6) |
          (bytes[i + 3] & 0x3f);
      }
    }
    if (size === 0) {
      out += String.fromCharCode(0xdc00 + b0); // surrogateescape
      i += 1;
    } else {
      out += String.fromCodePoint(cp);
      i += size;
    }
  }
  return out;
}

/**
 * Encode a `str` back to UTF-8 bytes with the `surrogateescape` handler:
 * lone surrogates in the U+DC80..U+DCFF range become the original raw byte.
 */
export function encodeUtf8SurrogateEscape(text) {
  const chunks = [];
  let plain = '';
  const flush = () => {
    if (plain) {
      chunks.push(Buffer.from(plain, 'utf8'));
      plain = '';
    }
  };
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp >= 0xdc80 && cp <= 0xdcff) {
      flush();
      chunks.push(Buffer.from([cp - 0xdc00]));
    } else if (isSurrogate(cp)) {
      flush();
      chunks.push(Buffer.from(backslashEscape(cp), 'ascii'));
    } else {
      plain += ch;
    }
  }
  flush();
  return Buffer.concat(chunks);
}

/**
 * Encode a `str` to UTF-8 with the `backslashreplace` handler, which is what
 * CPython installs on `sys.stderr`: unencodable code points (i.e. lone
 * surrogates) are rendered as their `\udcxx` escape text.
 */
export function encodeUtf8BackslashReplace(text) {
  const chunks = [];
  let plain = '';
  const flush = () => {
    if (plain) {
      chunks.push(Buffer.from(plain, 'utf8'));
      plain = '';
    }
  };
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (isSurrogate(cp)) {
      flush();
      chunks.push(Buffer.from(backslashEscape(cp), 'ascii'));
    } else {
      plain += ch;
    }
  }
  flush();
  return Buffer.concat(chunks);
}

function backslashEscape(cp) {
  if (cp <= 0xff) return '\\x' + hex(cp, 2);
  if (cp <= 0xffff) return '\\u' + hex(cp, 4);
  return '\\U' + hex(cp, 8);
}

