/**
 * The slice of `textwrap` and `shutil.get_terminal_size()` that `argparse`
 * relies on when it lays out usage and help text.
 */

/**
 * `shutil.get_terminal_size()`.
 *
 * CPython honours a valid positive $COLUMNS first, then queries the terminal
 * attached to *stdout* (not stderr), then falls back to 80 columns. Node's
 * `process.stdout.columns` is undefined unless stdout is a TTY, which lines up
 * with CPython's OSError-to-fallback path when stdout is a pipe or file.
 */
export function getTerminalColumns(fallback = 80) {
  const env = process.env.COLUMNS;
  if (typeof env === 'string') {
    const trimmed = env.trim();
    if (/^[+-]?\d+$/.test(trimmed)) {
      const columns = Number.parseInt(trimmed, 10);
      if (columns > 0) return columns;
    }
  }
  const tty = process.stdout && process.stdout.columns;
  if (typeof tty === 'number' && tty > 0) return tty;
  return fallback;
}

// Whitespace run collapsing, matching argparse's re.compile(r'\s+', re.ASCII).
const ASCII_WHITESPACE_RUN = /[ \t\n\r\f\v]+/g;

/** argparse's `HelpFormatter._whitespace_matcher.sub(' ', text).strip()`. */
export function collapseWhitespace(text) {
  return text.replace(ASCII_WHITESPACE_RUN, ' ').replace(/^ +| +$/g, '');
}

/**
 * Split text into `textwrap` chunks: whitespace runs, and words that may be
 * broken after an internal hyphen.
 */
function splitChunks(text) {
  const chunks = [];
  const pattern = /[ \t\n\r\f\v]+|[^\s-]+-+(?=[^\s-])|[^\s]+?(?=[ \t\n\r\f\v]|$)|[^\s]+/g;
  let match;
  while ((match = pattern.exec(text)) !== null) {
    if (match[0] === '') {
      pattern.lastIndex += 1;
      continue;
    }
    chunks.push(match[0]);
  }
  return chunks;
}

const IS_WHITESPACE = /^[ \t\n\r\f\v]+$/;

/**
 * `textwrap.wrap(text, width)` with the default options that argparse uses
 * (replace_whitespace, drop_whitespace and break_long_words all on).
 */
export function wrap(text, width) {
  const effectiveWidth = Math.max(1, width);
  const chunks = splitChunks(text);
  const lines = [];
  let index = 0;

  while (index < chunks.length) {
    // drop_whitespace: leading whitespace on a continuation line is discarded
    if (IS_WHITESPACE.test(chunks[index]) && lines.length > 0) {
      index += 1;
      continue;
    }
    const current = [];
    let length = 0;
    while (index < chunks.length) {
      const chunkLength = chunks[index].length;
      if (length + chunkLength > effectiveWidth) break;
      current.push(chunks[index]);
      length += chunkLength;
      index += 1;
    }
    // break_long_words: a single chunk wider than the line gets split
    if (index < chunks.length && chunks[index].length > effectiveWidth) {
      const space = effectiveWidth - length;
      if (space > 0) {
        current.push(chunks[index].slice(0, space));
        chunks[index] = chunks[index].slice(space);
      } else if (current.length === 0) {
        current.push(chunks[index].slice(0, effectiveWidth));
        chunks[index] = chunks[index].slice(effectiveWidth);
      }
    }
    // drop_whitespace: trailing whitespace is discarded
    while (current.length > 0 && IS_WHITESPACE.test(current[current.length - 1])) {
      current.pop();
    }
    if (current.length > 0) lines.push(current.join(''));
  }
  return lines;
}

