/**
 * Port of `argparse.HelpFormatter`.
 *
 * The layout arithmetic is reproduced exactly, because usage/help output is
 * byte-compared against CPython: the terminal width feeds `_max_help_position`,
 * which feeds the help column, which decides whether an option's help text sits
 * on the same line or the next one, and at what wrap width.
 */

import { getTerminalColumns, collapseWhitespace, wrap } from '../py/textwrap.mjs';
import { SUPPRESS } from './errors.mjs';

const LONG_BREAK = /\n\n\n+/g;

class HelpSection {
  constructor(formatter, parent, heading = null) {
    this.formatter = formatter;
    this.parent = parent;
    this.heading = heading;
    this.items = [];
  }

  formatHelp() {
    const f = this.formatter;
    if (this.parent !== null) f.indent();
    const itemHelp = f.joinParts(this.items.map(([fn, args]) => fn(...args)));
    if (this.parent !== null) f.dedent();

    if (!itemHelp) return '';

    let heading = '';
    if (this.heading !== SUPPRESS && this.heading !== null && this.heading !== undefined) {
      heading = ' '.repeat(f.currentIndent) + this.heading + ':\n';
    }
    return f.joinParts(['\n', heading, itemHelp, '\n']);
  }
}

export class HelpFormatter {
  constructor({ prog, indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    const effectiveWidth = width === null ? getTerminalColumns() - 2 : width;
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.maxHelpPosition = Math.min(
      maxHelpPosition,
      Math.max(effectiveWidth - 20, indentIncrement * 2),
    );
    this.width = effectiveWidth;
    this.currentIndent = 0;
    this.level = 0;
    this.actionMaxLength = 0;
    this.rootSection = new HelpSection(this, null);
    this.currentSection = this.rootSection;
  }

  indent() {
    this.currentIndent += this.indentIncrement;
    this.level += 1;
  }

  dedent() {
    this.currentIndent -= this.indentIncrement;
    this.level -= 1;
  }

  addItem(fn, args) {
    this.currentSection.items.push([fn, args]);
  }

  startSection(heading) {
    this.indent();
    const section = new HelpSection(this, this.currentSection, heading);
    this.addItem(() => section.formatHelp(), []);
    this.currentSection = section;
  }

  endSection() {
    this.currentSection = this.currentSection.parent;
    this.dedent();
  }

  addText(text) {
    if (text !== SUPPRESS && text !== null && text !== undefined) {
      this.addItem((value) => this.formatText(value), [text]);
    }
  }

  addUsage(usage, actions, groups, prefix = null) {
    if (usage !== SUPPRESS) {
      this.addItem((...args) => this.formatUsage(...args), [usage, actions, groups, prefix]);
    }
  }

  addArgument(action) {
    if (action.help === SUPPRESS) return;
    const invocationLength = this.formatActionInvocation(action).length;
    const actionLength = invocationLength + this.currentIndent;
    this.actionMaxLength = Math.max(this.actionMaxLength, actionLength);
    this.addItem((value) => this.formatAction(value), [action]);
  }

  addArguments(actions) {
    for (const action of actions) this.addArgument(action);
  }

  joinParts(parts) {
    return parts.filter((part) => part && part !== SUPPRESS).join('');
  }

  formatHelp() {
    let help = this.rootSection.formatHelp();
    if (help) {
      help = help.replace(LONG_BREAK, '\n\n');
      help = help.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
    }
    return help;
  }

  formatText(text) {
    const indent = ' '.repeat(this.currentIndent);
    const textWidth = Math.max(this.width - this.currentIndent, 11);
    return this.fillText(text, textWidth, indent) + '\n\n';
  }

  fillText(text, width, indent) {
    return wrap(collapseWhitespace(text), width)
      .map((line) => indent + line)
      .join('\n');
  }

  splitLines(text, width) {
    return wrap(collapseWhitespace(text), width);
  }

  formatUsage(usage, actions, groups, prefix) {
    const effectivePrefix = prefix === null || prefix === undefined ? 'usage: ' : prefix;

    const optionals = [];
    const positionals = [];
    for (const action of actions) {
      if (action.optionStrings.length > 0) optionals.push(action);
      else positionals.push(action);
    }

    const format = (acts) => this.formatActionsUsage(acts, groups);

    let text;
    if (usage !== null && usage !== undefined) {
      text = usage.replace(/%\(prog\)s/g, this.prog);
    } else if (actions.length === 0) {
      text = this.prog;
    } else {
      const actionUsage = format([...optionals, ...positionals]);
      text = [this.prog, actionUsage].filter((part) => part).join(' ');

      const textWidth = this.width - this.currentIndent;
      if (effectivePrefix.length + text.length > textWidth) {
        // Break the usage line into wrappable parts, exactly as CPython does:
        // bracketed groups stay intact, everything else splits on whitespace.
        const partRegexp = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
        const optParts = format(optionals).match(partRegexp) || [];
        const posParts = format(positionals).match(partRegexp) || [];

        const getLines = (parts, indent, linePrefix) => {
          const lines = [];
          let line = [];
          let lineLen = (linePrefix !== undefined ? linePrefix.length : indent.length) - 1;
          for (const part of parts) {
            if (lineLen + 1 + part.length > textWidth && line.length > 0) {
              lines.push(indent + line.join(' '));
              line = [];
              lineLen = indent.length - 1;
            }
            line.push(part);
            lineLen += 1 + part.length;
          }
          if (line.length > 0) lines.push(indent + line.join(' '));
          if (linePrefix !== undefined && lines.length > 0) {
            lines[0] = lines[0].slice(indent.length);
          }
          return lines;
        };

        let lines;
        if (effectivePrefix.length + this.prog.length <= 0.75 * textWidth) {
          // Short program name: hang the options off the end of it.
          const indent = ' '.repeat(effectivePrefix.length + this.prog.length + 1);
          if (optParts.length > 0) {
            lines = getLines([this.prog, ...optParts], indent, effectivePrefix);
            lines.push(...getLines(posParts, indent));
          } else if (posParts.length > 0) {
            lines = getLines([this.prog, ...posParts], indent, effectivePrefix);
          } else {
            lines = [this.prog];
          }
        } else {
          // Long program name: it gets a line of its own.
          const indent = ' '.repeat(effectivePrefix.length);
          lines = getLines([...optParts, ...posParts], indent);
          if (lines.length > 1) {
            lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
          }
          lines = [this.prog, ...lines];
        }
        text = lines.join('\n');
      }
    }

    return `${effectivePrefix}${text}\n\n`;
  }

  formatActionsUsage(actions, _groups) {
    const parts = [];
    for (const action of actions) {
      if (action.help === SUPPRESS) continue;
      if (action.optionStrings.length === 0) {
        parts.push(this.formatArgs(action, this.defaultMetavarForPositional(action)));
        continue;
      }
      const optionString = action.optionStrings[0];
      let part;
      if (action.nargs === 0) {
        part = optionString;
      } else {
        const defaultMetavar = this.defaultMetavarForOptional(action);
        part = `${optionString} ${this.formatArgs(action, defaultMetavar)}`;
      }
      if (!action.required) part = `[${part}]`;
      parts.push(part);
    }
    return parts.join(' ');
  }

  formatActionInvocation(action) {
    if (action.optionStrings.length === 0) {
      return this.metavarFor(action, this.defaultMetavarForPositional(action));
    }
    if (action.nargs === 0) {
      return action.optionStrings.join(', ');
    }
    const argsString = this.formatArgs(action, this.defaultMetavarForOptional(action));
    return action.optionStrings.map((option) => `${option} ${argsString}`).join(', ');
  }

  formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;
    let actionHeader = this.formatActionInvocation(action);
    let indentFirst = 0;

    if (!action.help) {
      // No help text: the invocation line stands alone.
      actionHeader = ' '.repeat(this.currentIndent) + actionHeader + '\n';
    } else if (actionHeader.length <= actionWidth) {
      // Short invocation: pad it out and start the help on the same line.
      actionHeader =
        ' '.repeat(this.currentIndent) + actionHeader.padEnd(actionWidth, ' ') + '  ';
      indentFirst = 0;
    } else {
      // Long invocation: the help text starts on the following line.
      actionHeader = ' '.repeat(this.currentIndent) + actionHeader + '\n';
      indentFirst = helpPosition;
    }

    const parts = [actionHeader];
    if (action.help && String(action.help).trim()) {
      const helpLines = this.splitLines(this.expandHelp(action), helpWidth);
      if (helpLines.length > 0) {
        parts.push(' '.repeat(indentFirst) + helpLines[0] + '\n');
        for (const line of helpLines.slice(1)) {
          parts.push(' '.repeat(helpPosition) + line + '\n');
        }
      }
    } else if (!actionHeader.endsWith('\n')) {
      parts.push('\n');
    }
    return this.joinParts(parts);
  }

  expandHelp(action) {
    return String(action.help).replace(/%\(prog\)s/g, this.prog);
  }

  metavarFor(action, defaultMetavar) {
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    if (action.choices !== null && action.choices !== undefined) {
      return `{${action.choices.join(',')}}`;
    }
    return defaultMetavar;
  }

  formatArgs(action, defaultMetavar) {
    const metavar = this.metavarFor(action, defaultMetavar);
    if (action.nargs === null || action.nargs === undefined) return metavar;
    if (action.nargs === '?') return `[${metavar}]`;
    if (action.nargs === '*') return `[${metavar} ...]`;
    if (action.nargs === '+') return `${metavar} [${metavar} ...]`;
    if (typeof action.nargs === 'number') {
      return new Array(action.nargs).fill(metavar).join(' ');
    }
    return metavar;
  }

  defaultMetavarForOptional(action) {
    return String(action.dest).toUpperCase();
  }

  defaultMetavarForPositional(action) {
    return String(action.dest);
  }
}

