/**
 * Port of `argparse.ArgumentParser` covering the behaviour the source program
 * can reach: three required long options taking a value, the implicit
 * `-h/--help`, prefix abbreviation, `--opt=value`, the negative-number
 * heuristic, short-option clusters, and CPython 3.12's exact error text.
 */

import { getArgs, getProgName } from '../py/argv.mjs';
import { writeStderr, writeStdout } from '../py/io.mjs';
import { reprStr } from '../py/repr.mjs';
import { ACTION_CLASSES, HelpAction, Action } from './actions.mjs';
import { ArgumentError, ArgumentTypeError, getActionName, SUPPRESS, SystemExit } from './errors.mjs';
import { HelpFormatter } from './formatter.mjs';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const PARSER = 'A...';
const REMAINDER = '...';
const OPTIONAL = '?';
const ZERO_OR_MORE = '*';
const ONE_OR_MORE = '+';

/** Equivalent of `argparse.Namespace`. */
export class Namespace {
  constructor(values = {}) {
    for (const [key, value] of Object.entries(values)) this[key] = value;
  }
  __repr__() {
    const parts = Object.keys(this).map((key) => `${key}=${reprStr(String(this[key]))}`);
    return `Namespace(${parts.join(', ')})`;
  }
}

export class ArgumentParser {
  constructor({
    prog = null,
    usage = null,
    description = null,
    epilog = null,
    prefixChars = '-',
    addHelp = true,
    allowAbbrev = true,
    formatterClass = HelpFormatter,
  } = {}) {
    this.prog = prog === null ? getProgName() : prog;
    this.usage = usage;
    this.description = description;
    this.epilog = epilog;
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;
    this.formatterClass = formatterClass;

    this.actions = [];
    this.optionStringActions = new Map();
    this.hasNegativeNumberOptionals = false;

    const defaultPrefix = prefixChars.includes('-') ? '-' : prefixChars[0];
    this.actionGroups = [
      { title: 'positional arguments', description: null, groupActions: [] },
      { title: 'options', description: null, groupActions: [] },
    ];
    this.positionalsGroup = this.actionGroups[0];
    this.optionalsGroup = this.actionGroups[1];

    if (addHelp) {
      this.addArgument([defaultPrefix + 'h', defaultPrefix.repeat(2) + 'help'], {
        action: 'help',
        default: SUPPRESS,
        help: 'show this help message and exit',
      });
    }
  }

  // ---------------------------------------------------------------- building

  /**
   * `parser.add_argument(...)`.
   *
   * @param {string|string[]} names one or more option strings, or a single
   *   positional destination name.
   */
  addArgument(names, options = {}) {
    const nameList = Array.isArray(names) ? names : [names];
    const isOptional = nameList.every(
      (name) => name.length > 0 && this.prefixChars.includes(name[0]),
    );

    let optionStrings = [];
    let dest = options.dest ?? null;

    if (isOptional) {
      optionStrings = nameList;
      if (dest === null) {
        const longOptions = optionStrings.filter(
          (name) => name.length > 1 && this.prefixChars.includes(name[1]),
        );
        const source = longOptions.length > 0 ? longOptions[0] : optionStrings[0];
        dest = trimPrefix(source, this.prefixChars).replace(/-/g, '_');
      }
    } else {
      if (nameList.length !== 1) {
        throw new Error('positional arguments accept exactly one name');
      }
      dest = dest === null ? nameList[0] : dest;
    }

    const ActionClass = ACTION_CLASSES[options.action ?? 'store'];
    if (!ActionClass) throw new Error(`unknown action: ${options.action}`);

    const action = new ActionClass({
      optionStrings,
      dest,
      nargs: options.nargs ?? null,
      constValue: options.const,
      defaultValue: 'default' in options ? options.default : null,
      type: options.type ?? null,
      choices: options.choices ?? null,
      required: options.required ?? false,
      help: options.help ?? null,
      metavar: options.metavar ?? null,
    });

    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) this.hasNegativeNumberOptionals = true;
    }
    const group = isOptional ? this.optionalsGroup : this.positionalsGroup;
    group.groupActions.push(action);
    return action;
  }

  // ----------------------------------------------------------------- parsing

  parseArgs(args = null, namespace = null) {
    const [ns, argv] = this.parseKnownArgs(args, namespace);
    if (argv.length > 0) {
      this.error(`unrecognized arguments: ${argv.join(' ')}`);
    }
    return ns;
  }

  parseKnownArgs(args = null, namespace = null) {
    const argStrings = args === null ? getArgs() : [...args];
    const ns = namespace === null ? new Namespace() : namespace;

    // Seed defaults for anything the command line does not supply.
    for (const action of this.actions) {
      if (action.dest === SUPPRESS) continue;
      if (Object.hasOwn(ns, action.dest)) continue;
      if (action.default === SUPPRESS) continue;
      ns[action.dest] = action.default;
    }

    try {
      return this.parseKnownArgsInner(argStrings, ns);
    } catch (err) {
      if (err instanceof ArgumentError) {
        this.error(err.message);
      }
      throw err;
    }
  }

  parseKnownArgsInner(argStrings, ns) {
    // Classify every token: 'O' = optional, 'A' = plain argument,
    // '-' = the "--" separator.
    const optionStringIndices = new Map();
    const patternParts = [];
    for (let i = 0; i < argStrings.length; i += 1) {
      if (argStrings[i] === '--') {
        patternParts.push('-');
        for (let j = i + 1; j < argStrings.length; j += 1) patternParts.push('A');
        break;
      }
      const optionTuple = this.parseOptional(argStrings[i]);
      if (optionTuple === null) {
        patternParts.push('A');
      } else {
        optionStringIndices.set(i, optionTuple);
        patternParts.push('O');
      }
    }
    const argStringsPattern = patternParts.join('');

    const seenActions = new Set();
    const seenNonDefaultActions = new Set();
    const extras = [];
    const positionals = this.actions.filter((action) => action.optionStrings.length === 0);

    const takeAction = (action, argumentStrings, optionString = null) => {
      seenActions.add(action);
      const argumentValues = this.getValues(action, argumentStrings);
      if (argumentValues !== action.default) seenNonDefaultActions.add(action);
      action.call(this, ns, argumentValues, optionString);
    };

    const consumeOptional = (startIndex) => {
      const argString = argStrings[startIndex];
      let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);
      const actionTuples = [];
      let stop;

      for (;;) {
        if (action === null) {
          extras.push(argString);
          return startIndex + 1;
        }

        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = this.matchArgument(action, 'A');
          const chars = this.prefixChars;
          const secondChar = optionString.length > 1 ? optionString[1] : '';

          if (argCount === 0 && !chars.includes(secondChar) && explicitArg !== '') {
            // A single-dash option that takes no value: the tail may be more
            // short options ("-xyz" == "-x -y -z") unless "=" was used.
            if (sep || chars.includes(explicitArg[0])) {
              throw new ArgumentError(
                getActionName(action),
                `ignored explicit argument ${reprStr(explicitArg)}`,
              );
            }
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this.optionStringActions.has(optionString)) {
              action = this.optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (!explicitArg) {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(
              getActionName(action),
              `ignored explicit argument ${reprStr(explicitArg)}`,
            );
          }
        } else {
          const start = startIndex + 1;
          const argCount = this.matchArgument(action, argStringsPattern.slice(start));
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
          break;
        }
      }

      for (const [act, args, optString] of actionTuples) takeAction(act, args, optString);
      return stop;
    };

    const consumePositionals = (startIndex) => {
      let index = startIndex;
      const argCounts = this.matchArgumentsPartial(positionals, argStringsPattern.slice(index));
      for (let i = 0; i < argCounts.length; i += 1) {
        const action = positionals[i];
        const args = argStrings.slice(index, index + argCounts[i]);
        index += argCounts[i];
        takeAction(action, args);
      }
      positionals.splice(0, argCounts.length);
      return index;
    };

    let startIndex = 0;
    const optionIndices = [...optionStringIndices.keys()];
    const maxOptionStringIndex = optionIndices.length > 0 ? Math.max(...optionIndices) : -1;

    while (startIndex <= maxOptionStringIndex) {
      const candidates = optionIndices.filter((index) => index >= startIndex);
      const nextOptionStringIndex = Math.min(...candidates);
      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
        if (startIndex !== nextOptionStringIndex) {
          extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
          startIndex = nextOptionStringIndex;
        }
      }
      startIndex = consumeOptional(nextOptionStringIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    // Required arguments are reported before unrecognized ones.
