export class Namespace {
  constructor(values = {}) {
    for (const [key, value] of Object.entries(values)) this[key] = value;
  }
  __repr__() {
    const parts = Object.keys(this).map((key) => `${key}=${reprStr(String(this[key]))}`);
    return `Namespace(${parts.join(', ')})`;
  }
