  } = {}) {
    this.prog = prog === null ? getProgName() : prog;
    this.usage = usage;
    this.description = description;
    this.epilog = epilog;
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;
    this.formatterClass = formatterClass;

    this.actions = [];
    this.optionStringActions = new Map();
    this.hasNegativeNumberOptionals = false;

    const defaultPrefix = prefixChars.includes('-') ? '-' : prefixChars[0];
    this.actionGroups = [
      { title: 'positional arguments', description: null, groupActions: [] },
      { title: 'options', description: null, groupActions: [] },
