/**
 * `OrderedMultiDict` (alias `OMD`) -- an insertion-ordered mapping that keeps
 * every value added for a key.
 *
 * Behaviour reproduced from observing the reference implementation:
 *   - `add(k, v)` appends a value and returns nothing.
 *   - `keys()` yields each distinct key once, in order of first insertion.
 *   - `getlist(k)` yields every value stored for `k`, in insertion order.
 *   - `items()` yields one pair per distinct key holding that key's *last*
 *     value; `items(true)` yields every (key, value) pair in insertion order.
 *   - `repr()` renders as `OrderedMultiDict([...])` over the full multi-value
 *     pair list, so a repeated key shows up more than once.
 *
 * Internally a per-key value list gives O(1) `getlist`, while a parallel pair
 * list preserves the exact interleaving needed for multi-value iteration.
 */

import { PyTuple, repr } from '../py/repr.mjs';
import { keyToken } from './keys.mjs';

export class OrderedMultiDict {
  /**
   * @param {Iterable<[any, any]>|OrderedMultiDict|null} initial optional
   *   initial pairs, applied in order via `addlist` semantics.
   */
  constructor(initial = null) {
    /** @type {Map<any, {key: any, values: any[]}>} first-insertion ordered */
    this._slots = new Map();
    /** @type {Array<[any, any]>} every pair, in insertion order */
    this._pairs = [];
    if (initial !== null && initial !== undefined) {
      this.updateExtend(initial);
    }
  }

  // ------------------------------------------------------------------ writing

  /** `omd.add(key, value)` -- append a value for `key`. Returns undefined. */
  add(key, value) {
    const token = keyToken(key);
    let slot = this._slots.get(token);
    if (slot === undefined) {
      slot = { key, values: [] };
      this._slots.set(token, slot);
    }
    slot.values.push(value);
    this._pairs.push([slot.key, value]);
  }

  /** `omd.addlist(key, values)` -- append several values for `key`. */
  addlist(key, values) {
    for (const value of values) this.add(key, value);
  }

  /** `omd[key] = value` -- discard existing values, keep only `value`. */
  setitem(key, value) {
    this.popall(key, null);
    this.add(key, value);
  }

  /** `del omd[key]` -- remove the key and every value stored for it. */
  delitem(key) {
    const token = keyToken(key);
    if (!this._slots.has(token)) throw new Error(`KeyError: ${repr(key)}`);
    this._slots.delete(token);
    this._pairs = this._pairs.filter(([pairKey]) => keyToken(pairKey) !== token);
  }

  /** Remove `key`, returning its last value (or `fallback`). */
  pop(key, fallback = undefined) {
    const token = keyToken(key);
    const slot = this._slots.get(token);
    if (slot === undefined) {
      if (fallback === undefined) throw new Error(`KeyError: ${repr(key)}`);
      return fallback;
    }
    const last = slot.values[slot.values.length - 1];
    this.delitem(key);
    return last;
  }

  /** Remove `key`, returning every value stored for it (or `fallback`). */
  popall(key, fallback = undefined) {
    const token = keyToken(key);
    const slot = this._slots.get(token);
    if (slot === undefined) {
      if (fallback === undefined) throw new Error(`KeyError: ${repr(key)}`);
      return fallback;
    }
    const values = [...slot.values];
    this.delitem(key);
    return values;
  }

  /** Merge another mapping, replacing values for keys already present. */
  update(other) {
    for (const [key, value] of pairsOf(other)) this.setitem(key, value);
  }

  /** Merge another mapping, appending values for keys already present. */
  updateExtend(other) {
    for (const [key, value] of pairsOf(other)) this.add(key, value);
  }

  clear() {
    this._slots.clear();
    this._pairs = [];
  }

  // ------------------------------------------------------------------ reading

  /** `omd[key]` -- the last value stored for `key`. */
  getitem(key) {
    const slot = this._slots.get(keyToken(key));
    if (slot === undefined) throw new Error(`KeyError: ${repr(key)}`);
    return slot.values[slot.values.length - 1];
  }

  /** `omd.get(key, default)` -- the last value stored for `key`. */
  get(key, fallback = null) {
    const slot = this._slots.get(keyToken(key));
    if (slot === undefined) return fallback;
    return slot.values[slot.values.length - 1];
  }

  /** `omd.getlist(key)` -- every value stored for `key`, in order. */
  getlist(key, fallback = null) {
    const slot = this._slots.get(keyToken(key));
    if (slot === undefined) return fallback === null ? [] : fallback;
    return [...slot.values];
  }

  has(key) {
    return this._slots.has(keyToken(key));
  }

  /** `omd.keys()` -- each distinct key once, in first-insertion order. */
  keys() {
    const result = [];
    for (const slot of this._slots.values()) result.push(slot.key);
    return result;
  }

