   * `omd.items(multi=False)` -- one `(key, last value)` pair per distinct key.
   * With `multi` true, every `(key, value)` pair in insertion order.
   */
  items(multi = false) {
    if (multi) return this._pairs.map(([key, value]) => new PyTuple([key, value]));
    const result = [];
    for (const slot of this._slots.values()) {
      result.push(new PyTuple([slot.key, slot.values[slot.values.length - 1]]));
    }
    return result;
  }

  /** Plain-object projection, mirroring `omd.todict()`. */
  todict(multi = false) {
    const result = new Map();
    for (const slot of this._slots.values()) {
      result.set(slot.key, multi ? [...slot.values] : slot.values[slot.values.length - 1]);
    }
