    const slot = this._slots.get(keyToken(key));
    return slot === undefined ? 0 : slot.values.length;
  }

  /** A shallow copy preserving all values and their order. */
  copy() {
    const clone = new this.constructor();
    for (const [key, value] of this._pairs) clone.add(key, value);
    return clone;
  }

  /** `inverted()` -- values become keys and vice versa. */
  inverted() {
    const result = new this.constructor();
    for (const [key, value] of this._pairs) result.add(value, key);
    return result;
  }

  /** `len(omd)` -- the number of distinct keys. */
  __len__() {
    return this._slots.size;
  }

  get size() {
    return this._slots.size;
  }

  /** Iterating an OMD yields its distinct keys, as with a Python mapping. */
  *[Symbol.iterator]() {
    for (const slot of this._slots.values()) yield slot.key;
  }

  *iterkeys() {
    yield* this[Symbol.iterator]();
  }

  *iteritems(multi = false) {
    yield* this.items(multi);
  }

  *itervalues(multi = false) {
    yield* this.values(multi);
  }

  /** Equal when both hold the same multi-value pair sequence. */
  equals(other) {
    if (!(other instanceof OrderedMultiDict)) return false;
    if (this._pairs.length !== other._pairs.length) return false;
    for (let i = 0; i < this._pairs.length; i += 1) {
      if (keyToken(this._pairs[i][0]) !== keyToken(other._pairs[i][0])) return false;
      if (this._pairs[i][1] !== other._pairs[i][1]) return false;
    }
    return true;
  }

  /** `repr(omd)` -- e.g. `OrderedMultiDict([('a', 1), ('a', 2)])`. */
  __repr__() {
    const className = this.constructor.name;
    const body = this._pairs.map(([key, value]) => repr(new PyTuple([key, value]))).join(', ');
    return `${className}([${body}])`;
  }

  /** `str(omd)` falls through to `repr(omd)`, as in Python. */
  __str__() {
    return this.__repr__();
  }
}

/** Normalise anything mapping-like into an iterable of pairs. */
function pairsOf(source) {
  if (source instanceof OrderedMultiDict) return source._pairs.map(([k, v]) => [k, v]);
  if (source instanceof Map) return [...source.entries()];
  if (Array.isArray(source)) return source.map((pair) => [pair[0], pair[1]]);
