import { OMD, OrderedMultiDict } from '/output/lib/dictutils/index.mjs';
import { repr, list, len } from '/output/lib/index.mjs';

const ck = (label, got, want) => {
  const ok = got === want;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${label}: ${got}${ok ? '' : `  (want ${want})`}`);
  return ok;
};
let fails = 0;
const t = (l, g, w) => { if (!ck(l, g, w)) fails++; };

const o = new OMD();
t('alias', OMD === OrderedMultiDict, true);
t('empty repr', repr(o), 'OrderedMultiDict([])');
t('empty len', len(o), 0);
o.add('k', 1); o.add('k', 2); o.add('j', 3);
t('repr multi', repr(o), "OrderedMultiDict([('k', 1), ('k', 2), ('j', 3)])");
t('keys', repr(list(o.keys())), "['k', 'j']");
t('getlist', repr(o.getlist('k')), '[1, 2]');
t('getlist missing', repr(o.getlist('zz')), '[]');
t('items last', repr(list(o.items())), "[('k', 2), ('j', 3)]");
t('items multi', repr(list(o.items(true))), "[('k', 1), ('k', 2), ('j', 3)]");
t('values', repr(o.values()), '[2, 3]');
t('values multi', repr(o.values(true)), '[1, 2, 3]');
t('get', o.get('k'), 2);
t('getitem', o.getitem('j'), 3);
t('len unique', len(o), 2);
t('countOf', o.countOf('k'), 2);
t('iter keys', repr(list(o)), "['k', 'j']");

const c = o.copy();
t('copy repr', repr(c), repr(o));
t('copy eq', c.equals(o), true);
c.setitem('k', 9);
t('setitem collapses', repr(c), "OrderedMultiDict([('j', 3), ('k', 9)])");
t('orig untouched', repr(o), "OrderedMultiDict([('k', 1), ('k', 2), ('j', 3)])");
t('not eq after edit', c.equals(o), false);

const p = o.copy();
t('popall', repr(p.popall('k')), '[1, 2]');
t('after popall', repr(p), "OrderedMultiDict([('j', 3)])");
t('pop default', p.pop('nope', 'D'), 'D');
t('popall default', repr(p.popall('nope', [])), '[]');

const q = o.copy();
t('pop last', q.pop('k'), 2);
t('after pop', repr(q), "OrderedMultiDict([('j', 3)])");

const inv = new OMD([['a', 'x'], ['b', 'x']]).inverted();
t('inverted', repr(inv), "OrderedMultiDict([('x', 'a'), ('x', 'b')])");
t('ctor pairs', repr(new OMD([['a', 1], ['a', 2]])), "OrderedMultiDict([('a', 1), ('a', 2)])");

// Python dict key identity: True == 1 == 1.0 collide, first key object wins.
const k = new OMD();
k.add(1, 'int'); k.add(true, 'bool'); k.add(1.0, 'float');
t('int/bool/float collide', repr(list(k.keys())), '[1]');
t('collide values', repr(k.getlist(1)), "['int', 'bool', 'float']");

// Keys that would collide with Object.prototype members must stay distinct.
const proto = new OMD();
proto.add('constructor', 1); proto.add('__proto__', 2); proto.add('toString', 3);
t('proto-safe keys', repr(list(proto.keys())), "['constructor', '__proto__', 'toString']");
t('proto-safe getlist', repr(proto.getlist('__proto__')), '[2]');

// clear / has / todict
const z = o.copy(); z.clear();
t('clear', repr(z), 'OrderedMultiDict([])');
t('has', o.has('k') && !o.has('zzz'), true);
t('todict last', repr(list(o.todict().values())), '[2, 3]');
t('todict multi', repr(list(o.todict(true).values())), '[[1, 2], [3]]');

// repr of nested/odd values
t('tuple 1-elem', repr(list(new OMD([['a', 1]]).items()).slice(0, 1)), "[('a', 1)]");
t('nested list', repr([[1, 2], 'x']), "[[1, 2], 'x']");
t('None/True/False', repr([null, true, false]), '[None, True, False]');

console.log(fails === 0 ? '\nALL OMD/repr UNIT TESTS PASS' : `\n${fails} UNIT TEST FAILURES`);
process.exit(fails === 0 ? 0 : 1);
EOF
