/**
 * `sys.argv` reconstruction.
 *
 * Node decodes `process.argv` lossily: a command-line byte sequence that is
 * not valid UTF-8 arrives as U+FFFD, whereas CPython decodes argv with the
 * filesystem encoding plus the `surrogateescape` handler and therefore keeps
 * the original bytes recoverable as lone surrogates. On Linux we can recover
 * the true bytes from `/proc/self/cmdline` and decode them exactly the way
 * CPython does; everywhere else we fall back to `process.argv`.
 */

import { readFileSync } from 'node:fs';
import { basename } from 'node:path';

import { decodeUtf8SurrogateEscape } from './codecs.mjs';

const REPLACEMENT_CHAR = '�';

/**
 * Raw argv of the current process as a list of byte slices, or null if it is
 * unavailable.
 *
 * `/proc/self/cmdline` holds NUL-*terminated* entries, so we cut at every NUL
 * and take what precedes it. Trimming trailing NULs instead would silently
 * swallow a genuinely empty final argument and misalign everything.
 */
function readRawCmdline() {
  let buf;
  try {
    buf = readFileSync('/proc/self/cmdline');
  } catch {
    return null;
  }
  if (buf.length === 0) return null;

  const parts = [];
  let start = 0;
  for (let i = 0; i < buf.length; i += 1) {
    if (buf[i] === 0) {
      parts.push(buf.subarray(start, i));
      start = i + 1;
    }
  }
  // Defensive: a final entry without its terminator (should not happen).
  if (start < buf.length) parts.push(buf.subarray(start));
  return parts;
}

/**
 * Sanity-check that a recovered byte slice really corresponds to the argument
 * Node reported, so a surprising `/proc` layout degrades to the cooked value
 * instead of shifting arguments around.
 */
function alignsWith(rawBytes, cookedArg) {
  const decoded = decodeUtf8SurrogateEscape(rawBytes);
  if (decoded === cookedArg) return true;
  // Node replaces every undecodable byte with U+FFFD; CPython keeps it as a
  // lone surrogate. Same length in code units, differing only at those spots.
  if (!cookedArg.includes(REPLACEMENT_CHAR)) return false;
  if (decoded.length !== cookedArg.length) return false;
  for (let i = 0; i < decoded.length; i += 1) {
    if (decoded[i] === cookedArg[i]) continue;
    if (cookedArg[i] !== REPLACEMENT_CHAR) return false;
  }
  return true;
}

/**
 * The user-supplied arguments, i.e. Python's `sys.argv[1:]`.
 *
 * Only the *tail* of the raw command line is trusted, matched to
 * `process.argv.slice(2)` by count. That keeps the mapping correct even when
 * node itself was invoked with extra interpreter flags.
 */
export function getArgs() {
  const cooked = process.argv.slice(2);
  const raw = readRawCmdline();
  if (raw === null || raw.length < cooked.length) return cooked;

  const tail = raw.slice(raw.length - cooked.length);
  for (let i = 0; i < cooked.length; i += 1) {
    if (!alignsWith(tail[i], cooked[i])) return cooked;
  }
  return tail.map((bytes) => decodeUtf8SurrogateEscape(bytes));
}

/**
 * Default program name. `argparse` uses `os.path.basename(sys.argv[0])`, so
 * the Node port derives it from the entry script in the same way.
 */
export function getProgName() {
  const script = process.argv[1];
  if (typeof script === 'string' && script.length > 0) return basename(script);
  return ''; // CPython yields '' when sys.argv[0] is empty
}

