// Derive the reference implementation's printability table purely by observing
// its output: feed it every code point (dot-separated) and see which ones come
// back escaped. Emits non-printable ranges for cp >= 0x80.
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test6_executable';
const BATCH = 4096;
const SEP = '.';

function probe(codePoints) {
  const text = codePoints.map((cp) => String.fromCodePoint(cp)).join(SEP);
  const out = execFileSync(EXE, ['--a', text, '--b', 'x', '--c', 'y'], {
    encoding: 'utf8',
    maxBuffer: 1 << 28,
  });
  const line = out.split('\n')[4]; // list(omd.keys()) -> ['<repr body>']
  const start = line.indexOf("['");
  const end = line.lastIndexOf("']");
  if (start !== 0 || end < 0) throw new Error('unexpected output: ' + line.slice(0, 80));
  const body = line.slice(start + 2, end);
  const tokens = body.split(SEP);
  if (tokens.length !== codePoints.length) {
    throw new Error(`token count ${tokens.length} != ${codePoints.length}`);
  }
  return tokens.map((tok) => tok.startsWith('\\')); // true => non-printable
}

const nonPrintable = [];
let batch = [];
let done = 0;
const flush = () => {
  if (batch.length === 0) return;
  const flags = probe(batch);
  for (let i = 0; i < batch.length; i += 1) if (flags[i]) nonPrintable.push(batch[i]);
  done += batch.length;
  if (done % 65536 < BATCH) process.stderr.write(`  probed ${done}\n`);
  batch = [];
};

for (let cp = 0x80; cp <= 0x10ffff; cp += 1) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue; // cannot travel through argv
  batch.push(cp);
  if (batch.length === BATCH) flush();
}
flush();

// Collapse to ranges, folding the surrogate block back in (always Cs).
const set = new Set(nonPrintable);
for (let cp = 0xd800; cp <= 0xdfff; cp += 1) set.add(cp);
const sorted = [...set].sort((a, b) => a - b);
const ranges = [];
for (const cp of sorted) {
  const last = ranges[ranges.length - 1];
  if (last && cp === last[1] + 1) last[1] = cp;
  else ranges.push([cp, cp]);
}

console.log(`code points probed: ${done}`);
console.log(`non-printable code points (>=0x80): ${sorted.length}`);
console.log(`ranges: ${ranges.length}`);
writeFileSync('/tmp/nonprintable.json', JSON.stringify(ranges));

// Cross-check against the host's live ICU tables; the delta should be exactly
// the code points added in the newer Unicode version Node ships.
const NP = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
const icuSays = (cp) => (cp >= 0xd800 && cp <= 0xdfff ? true : NP.test(String.fromCodePoint(cp)));
const onlyRef = [];
const onlyIcu = [];
for (let cp = 0x80; cp <= 0x10ffff; cp += 1) {
  const ref = set.has(cp);
  const icu = icuSays(cp);
  if (ref && !icu) onlyRef.push(cp);
  else if (!ref && icu) onlyIcu.push(cp);
}
const fmt = (a) => a.slice(0, 12).map((c) => 'U+' + c.toString(16).toUpperCase()).join(' ');
console.log(`node unicode version: ${process.versions.unicode}`);
console.log(`non-printable per reference but printable per ICU: ${onlyRef.length}  ${fmt(onlyRef)}${onlyRef.length > 12 ? ' ...' : ''}`);
console.log(`printable per reference but non-printable per ICU: ${onlyIcu.length}  ${fmt(onlyIcu)}${onlyIcu.length > 12 ? ' ...' : ''}`);

