// Emit /output/lib/py/unicodedata.mjs from the table derived in gentable.mjs.
import { readFileSync, writeFileSync } from 'node:fs';

const ranges = JSON.parse(readFileSync('/tmp/nonprintable.json', 'utf8'));

// Pack as "gap.len" pairs in base-36: gap = distance from the previous range's
// end, len = range length minus one. Both are tiny, so this stays compact.
let cursor = 0;
const tokens = ranges.map(([start, end]) => {
  const gap = start - cursor;
  const len = end - start;
  cursor = end + 1;
  return gap.toString(36) + '.' + len.toString(36);
});
const packed = tokens.join(',');

// Wrap the packed string so the source file stays readable.
const CHUNK = 96;
const lines = [];
for (let i = 0; i < packed.length; i += CHUNK) {
  lines.push("  '" + packed.slice(i, i + CHUNK) + "'");
}

const total = ranges.reduce((sum, [s, e]) => sum + (e - s + 1), 0);

const content = `/**
 * Pinned table of non-printable code points, for code points >= U+0080.
 *
 * CPython decides printability from the Unicode General_Category tables that
 * its own build ships (categories Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs are all
 * non-printable). Asking the host runtime instead -- e.g. via the ECMAScript
 * \\p{...} property escapes -- makes the answer depend on whichever Unicode
 * version the local ICU happens to carry, and the two do not agree: a runtime
 * one version ahead reports the newly assigned code points as printable, while
 * the reference still has them unassigned (Cn) and therefore escapes them.
 * That would make repr() output vary by Node build.
 *
 * So the table is pinned here instead. It was derived black-box, by feeding
 * every code point from U+0080 to U+10FFFF through the reference program and
 * recording which ones came back escaped: ${total.toLocaleString('en-US')} non-printable code
 * points in ${ranges.length} contiguous ranges. The surrogate block U+D800-U+DFFF, which
 * cannot travel through argv, is included on the strength of its category (Cs).
 *
 * Encoding: comma-separated "gap.len" pairs in base-36, where gap is the
 * distance from the end of the previous range and len is the range's length
 * minus one.
 */

const PACKED_NONPRINTABLE_RANGES =
${lines.join(' +\n')};

/** Flattened [start0, end0, start1, end1, ...], ascending and disjoint. */
const RANGES = (() => {
  const tokens = PACKED_NONPRINTABLE_RANGES.split(',');
  const flat = new Int32Array(tokens.length * 2);
  let cursor = 0;
  for (let i = 0; i < tokens.length; i += 1) {
    const dot = tokens[i].indexOf('.');
    const start = cursor + Number.parseInt(tokens[i].slice(0, dot), 36);
    const end = start + Number.parseInt(tokens[i].slice(dot + 1), 36);
    flat[i * 2] = start;
    flat[i * 2 + 1] = end;
    cursor = end + 1;
  }
  return flat;
})();

/** Number of ranges in the table (exported for tests). */
export const NONPRINTABLE_RANGE_COUNT = RANGES.length / 2;

/**
 * True when \`cp\` (>= 0x80) falls in a non-printable category. Binary search
 * over the pinned ranges.
 */
export function isNonPrintableAbove7f(cp) {
  let lo = 0;
  let hi = RANGES.length / 2 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < RANGES[mid * 2]) hi = mid - 1;
    else if (cp > RANGES[mid * 2 + 1]) lo = mid + 1;
    else return true;
  }
  return false;
}
`;

writeFileSync('/output/lib/py/unicodedata.mjs', content);
console.log(`wrote /output/lib/py/unicodedata.mjs`);
console.log(`ranges=${ranges.length} nonprintable=${total} packedChars=${packed.length}`);

