/**
 * Unicode helpers mirroring CPython's notion of "printable".
 *
 * CPython's `Py_UNICODE_ISPRINTABLE` (used by `str.__repr__` and
 * `str.isprintable`) treats a code point as non-printable when its Unicode
 * General_Category is one of Cc, Cf, Cs, Co, Cn, Zl, Zp or Zs -- with the
 * single exception of U+0020 SPACE, which is always printable.
 *
 * For code points at or above U+0080 the answer comes from the pinned table in
 * `unicodedata.mjs` rather than from the host runtime's property escapes, so
 * that output does not shift when the local ICU carries a different Unicode
 * version than the reference. See that module for the details.
 */

import { isNonPrintableAbove7f } from './unicodedata.mjs';

/** Lowest and highest UTF-16 surrogate code points. */
export const SURROGATE_MIN = 0xd800;
export const SURROGATE_MAX = 0xdfff;

/** True when `cp` is a lone/paired surrogate code point (category Cs). */
export function isSurrogate(cp) {
  return cp >= SURROGATE_MIN && cp <= SURROGATE_MAX;
}

/**
 * Equivalent of CPython's `Py_UNICODE_ISPRINTABLE` for a single code point.
 *
 * Below U+0080 the categories are fixed: the C0 controls and U+007F are Cc,
 * and everything from SPACE to TILDE is printable.
 */
export function isPrintableCodePoint(cp) {
  if (cp < 0x80) return cp >= 0x20 && cp <= 0x7e;
  return !isNonPrintableAbove7f(cp);
}

/**
 * Iterate a JS string by code point, the way Python iterates a `str`.
 *
 * The built-in string iterator already yields astral characters as a single
 * item and unpaired surrogates on their own, which matches Python's model of
 * a string as a sequence of code points (including the lone surrogates that
 * `surrogateescape` decoding can produce).
 */
export function* codePointsOf(text) {
  for (const ch of text) yield [ch, ch.codePointAt(0)];
}

/** Zero-padded lowercase hex, as used by Python's escape sequences. */
export function hex(cp, width) {
  return cp.toString(16).padStart(width, '0');
}

