// End-to-end differential sweep of the entire Unicode code point space:
// batch code points into argv strings and byte-compare the FULL stdout of the
// reference executable against the Node port.
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test6_executable';
const SHIM = '/tmp/prog/test6_executable';
const BATCH = 3000;

function run(cmd, args, argv) {
  try {
    return execFileSync(cmd, [...args, ...argv], { maxBuffer: 1 << 28 });
  } catch (err) {
    return Buffer.concat([err.stdout ?? Buffer.alloc(0), err.stderr ?? Buffer.alloc(0)]);
  }
}

let batches = 0;
let mismatches = 0;
const failing = [];

function compare(codePoints) {
  // Spread the batch across all three arguments so the key and both values are
  // exercised, with a dot separator so a failure can be bisected.
  const third = Math.ceil(codePoints.length / 3);
  const parts = [0, 1, 2].map((i) =>
    codePoints
      .slice(i * third, (i + 1) * third)
      .map((cp) => String.fromCodePoint(cp))
      .join('.'),
  );
  const argv = ['--a', parts[0] || 'k', '--b', parts[1] || 'v', '--c', parts[2] || 'w'];
  const py = run(EXE, [], argv);
  const js = run('node', [SHIM], argv);
  batches += 1;
  if (!py.equals(js)) {
    mismatches += 1;
    for (const cp of codePoints) {
      const one = ['--a', String.fromCodePoint(cp), '--b', 'v', '--c', 'w'];
      if (!run(EXE, [], one).equals(run('node', [SHIM], one))) {
        failing.push(cp);
        if (failing.length > 40) return;
      }
    }
  }
}

let batch = [];
for (let cp = 1; cp <= 0x10ffff; cp += 1) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (cp === 0x2e) continue; // the separator itself
  batch.push(cp);
  if (batch.length === BATCH) {
    compare(batch);
    batch = [];
    if (batches % 50 === 0) process.stderr.write(`  batches=${batches} mismatches=${mismatches}\n`);
  }
}
if (batch.length) compare(batch);

console.log(`batches compared: ${batches}`);
console.log(`batches with a byte difference: ${mismatches}`);
if (failing.length) {
  console.log(
    'failing code points: ' + failing.map((c) => 'U+' + c.toString(16).toUpperCase()).join(' '),
  );
} else {
  console.log('ALL CODE POINTS MATCH END-TO-END');
}
